-- Norway deep-dive page translations: page fields, stats, cards, steps, portal.
-- No penalty rows (no fine schedule discussed on the static page).

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'es', 'Peppol descentralizado (EHF 3.0)', 'Esta página de análisis refleja la orientación técnica disponible públicamente a julio de 2026 y se proporciona a título informativo general, no como asesoramiento legal o fiscal. La normativa técnica pendiente de Skattedirektoratet (prevista para el 15 de diciembre de 2026) precisará los detalles del formato de factura, las exenciones y los criterios de contabilidad digital — confirme los requisitos actuales directamente con Skatteetaten antes de construir una integración.', 'El mandato noruego ya es una ley genuinamente promulgada, no una propuesta — y es deliberadamente asimétrico: la emisión llega tres años antes que la recepción.', 'EHF es el nombre propio noruego de lo que, en el fondo, es un documento Peppol BIS Billing 3.0 — no hay un esquema nacional separado que aprender.', 'El mandato noruego es deliberadamente asimétrico durante tres años — una decisión de diseño, no un descuido, destinada a dar tiempo a los compradores para ponerse al día.', 'La adopción voluntaria existente en Noruega ya es alta (84–89 %), por lo que para muchas empresas esto consiste en formalizar una práctica ya existente.', 'Todavía no existe un modelo de compensación ni un reporte en tiempo real — pero la infraestructura que se está construyendo crea silenciosamente las condiciones previas para uno.' FROM countries WHERE name_en = 'Norway';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'de', 'Dezentrales Peppol (EHF 3.0)', 'Diese Länderanalyse spiegelt öffentlich verfügbare technische Hinweise mit Stand Juli 2026 wider und dient der allgemeinen Information, nicht als Rechts- oder Steuerberatung. Die noch ausstehenden technischen Vorschriften von Skattedirektoratet (fällig bis 15. Dezember 2026) werden Details zu Rechnungsformat, Ausnahmen und Kriterien für die digitale Buchführung präzisieren — bestätigen Sie aktuelle Anforderungen direkt bei Skatteetaten, bevor Sie eine Integration aufbauen.', 'Norwegens Pflicht ist inzwischen tatsächlich erlassenes Gesetz, kein Vorschlag mehr — und bewusst asymmetrisch: die Ausstellungspflicht kommt drei Jahre vor der Empfangspflicht.', 'EHF ist Norwegens eigener Name für das, was im Kern ein Peppol-BIS-Billing-3.0-Dokument ist — es gibt kein separates nationales Schema zu erlernen.', 'Norwegens Pflicht ist drei Jahre lang bewusst asymmetrisch gestaltet — eine Designentscheidung, kein Versehen, um Käufern Zeit zum Aufholen zu geben.', 'Norwegens bestehende freiwillige Nutzung ist bereits hoch (84–89 %), sodass es für viele Unternehmen vor allem darum geht, bereits gelebte Praxis zu formalisieren.', 'Es gibt noch kein Clearing-Modell oder Echtzeitmeldung — aber die im Aufbau befindliche Infrastruktur schafft still die Voraussetzungen dafür.' FROM countries WHERE name_en = 'Norway';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'fr', 'Peppol décentralisé (EHF 3.0)', 'Cette analyse par pays reflète les directives techniques publiquement disponibles à juillet 2026 et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Les règlements techniques restants de Skattedirektoratet (attendus pour le 15 décembre 2026) préciseront le détail du format de facture, les exemptions et les critères de comptabilité numérique — confirmez les exigences actuelles directement auprès de Skatteetaten avant de construire une intégration.', 'L''obligation norvégienne est désormais une loi véritablement promulguée, et non une simple proposition — et elle est délibérément asymétrique : l''émission arrive trois ans avant la réception.', 'EHF est le nom propre norvégien de ce qui, en réalité, est un document Peppol BIS Billing 3.0 — il n''y a pas de schéma national distinct à apprendre.', 'L''obligation norvégienne est délibérément asymétrique pendant trois ans — un choix de conception, pas un oubli, visant à laisser aux acheteurs le temps de se mettre à niveau.', 'L''adoption volontaire existante en Norvège est déjà élevée (84–89 %), de sorte que pour de nombreuses entreprises, il s''agit surtout de formaliser une pratique déjà en place.', 'Aucun modèle de contrôle ni de déclaration en temps réel n''existe encore — mais l''infrastructure en cours de construction crée discrètement les conditions préalables à sa mise en place.' FROM countries WHERE name_en = 'Norway';

