INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Formato', '[["Formato nacional", "EHF 3.0 (Elektronisk Handelsformat)"], ["Estándar subyacente", "Peppol BIS Billing 3.0 / UBL, EN 16931"], ["Transfronterizo", "Peppol BIS aceptado directamente"]]', 'EHF se utiliza normalmente para transacciones nacionales, mientras que Peppol BIS gestiona tanto las transacciones nacionales como las transfronterizas — a efectos de cumplimiento, ambos satisfacen el requisito legal por igual.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Norway' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Format', '[["Nationales Format", "EHF 3.0 (Elektronisk Handelsformat)"], ["Zugrunde liegender Standard", "Peppol BIS Billing 3.0 / UBL, EN 16931"], ["Grenzüberschreitend", "Peppol BIS wird direkt akzeptiert"]]', 'EHF wird typischerweise für inländische Transaktionen verwendet, während Peppol BIS sowohl inländische als auch grenzüberschreitende Transaktionen abdeckt — für Konformitätszwecke erfüllen beide die gesetzliche Anforderung gleichermaßen.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Norway' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Format', '[["Format national", "EHF 3.0 (Elektronisk Handelsformat)"], ["Norme sous-jacente", "Peppol BIS Billing 3.0 / UBL, EN 16931"], ["Transfrontalier", "Peppol BIS accepté directement"]]', 'EHF est généralement utilisé pour les transactions nationales tandis que Peppol BIS couvre à la fois les transactions nationales et transfrontalières — à des fins de conformité, les deux satisfont également à l''exigence légale.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Norway' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Identificadores', '[["Esquema de participante", "0192 (código ICD para el organisasjonsnummer noruego)"], ["Abreviatura habitual", "\"0192\" y \"NO ORGNR\" en la documentación de proveedores"]]', 'La identidad de enrutamiento está vinculada directamente al número de organización — si este campo es incorrecto, la entrega simplemente falla, sin importar lo correcto que sea el resto de la factura.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Norway' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Kennungen', '[["Teilnehmerschema", "0192 (ICD-Code für die norwegische organisasjonsnummer)"], ["Gängige Kurzform", "\"0192\" und \"NO ORGNR\" in der Anbieterdokumentation"]]', 'Die Routing-Identität ist direkt an die Organisationsnummer geknüpft — ist dieses Feld falsch, schlägt die Zustellung schlicht fehl, unabhängig davon, wie korrekt der Rest der Rechnung ist.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Norway' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Identifiants', '[["Schéma de participant", "0192 (code ICD pour le organisasjonsnummer norvégien)"], ["Abréviation courante", "« 0192 » et « NO ORGNR » dans la documentation des fournisseurs"]]', 'L''identité de routage est directement liée au numéro d''organisation — si ce champ est incorrect, la livraison échoue tout simplement, quelle que soit l''exactitude du reste de la facture.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Norway' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Entidades extranjeras', '[["Alcance", "Los mismos requisitos EHF que las empresas noruegas"], ["Desencadenante", "Obligaciones contables locales conforme a la Ley de Contabilidad noruega"]]', 'Si una entidad extranjera tiene obligaciones contables noruegas, no existe una versión más ligera del mandato — se aplican exactamente las mismas normas EHF al facturar a socios comerciales nacionales.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Norway' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Ausländische Unternehmen', '[["Umfang", "Dieselben EHF-Anforderungen wie für norwegische Unternehmen"], ["Auslöser", "Lokale Buchführungspflichten nach dem norwegischen Buchführungsgesetz"]]', 'Hat ein ausländisches Unternehmen norwegische Buchführungspflichten, gibt es keine abgeschwächte Version der Pflicht — beim Rechnungsstellen an inländische Geschäftspartner gelten exakt dieselben EHF-Regeln.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Norway' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Entités étrangères', '[["Périmètre", "Mêmes exigences EHF que pour les entreprises norvégiennes"], ["Déclencheur", "Obligations comptables locales au titre de la loi norvégienne sur la comptabilité"]]', 'Si une entité étrangère est soumise à des obligations comptables norvégiennes, il n''existe pas de version allégée de l''obligation — les mêmes règles EHF s''appliquent exactement lors de la facturation à des partenaires commerciaux nationaux.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Norway' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Exenciones', '[["Pequeñas empresas individuales", "Facturación inferior a 50.000 NOK, si no están registradas a efectos de IVA"], ["B2C", "Explícitamente excluido del mandato"]]', 'Skattedirektoratet está evaluando por separado un futuro marco de recibos electrónicos B2C — algo a vigilar, pero que no forma parte de la reforma B2B actual.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Norway' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Ausnahmen', '[["Kleine Einzelunternehmen", "Umsatz unter 50.000 NOK, sofern nicht umsatzsteuerpflichtig registriert"], ["B2C", "Ausdrücklich von der Pflicht ausgenommen"]]', 'Ein künftiger B2C-E-Beleg-Rahmen wird von Skattedirektoratet separat geprüft — beobachtenswert, aber nicht Teil der aktuellen B2B-Reform.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Norway' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Exemptions', '[["Petites entreprises individuelles", "Chiffre d''affaires inférieur à 50 000 NOK, si non assujetties à la TVA"], ["B2C", "Explicitement exclu de l''obligation"]]', 'Un futur cadre de reçus électroniques B2C est évalué séparément par Skattedirektoratet — à surveiller, mais ne fait pas partie de la réforme B2B actuelle.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Norway' AND dc.section = 'file_format' AND dc.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Modelo de red', '[["Modelo", "Peppol de cuatro esquinas (descentralizado)"], ["Enrutamiento", "Cualquier Punto de Acceso puede enrutar a cualquier otro"], ["Autoridad de compensación", "Ninguna"]]', 'No existe ningún requisito de conexiones punto a punto entre socios comerciales — se trata de la misma arquitectura que impulsa los mandatos B2B de Bélgica y el Reino Unido.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Norway' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Netzwerkmodell', '[["Modell", "Peppol-Vier-Ecken-Modell (dezentral)"], ["Routing", "Jeder Access Point kann zu jedem anderen weiterleiten"], ["Clearing-Behörde", "Keine"]]', 'Es besteht keine Pflicht zu Punkt-zu-Punkt-Verbindungen zwischen Handelspartnern — dies ist dieselbe Architektur, die auch die B2B-Pflichten Belgiens und des Vereinigten Königreichs antreibt.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Norway' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Modèle de réseau', '[["Modèle", "Peppol à quatre coins (décentralisé)"], ["Routage", "N''importe quel Access Point peut acheminer vers n''importe quel autre"], ["Autorité de contrôle", "Aucune"]]', 'Il n''y a aucune exigence de connexions point à point entre partenaires commerciaux — c''est la même architecture qui alimente les obligations B2B de la Belgique et du Royaume-Uni.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Norway' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Registro ELMA', '[["Nombre completo", "Elektronisk Mottakeradresseregister"], ["Operador", "DFØ (Agencia noruega de administración pública y financiera)"], ["Función", "Publicador Nacional de Metadatos de Servicio (SMP), integrado en el directorio Peppol"]]', 'Los emisores deben consultar automáticamente ELMA para verificar la dirección de entrega electrónica y la capacidad del comprador antes de transmitir — esta consulta es lo que determina si la obligación de emisión de 2027 se aplica a un destinatario concreto.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Norway' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'ELMA-Register', '[["Vollständiger Name", "Elektronisk Mottakeradresseregister"], ["Betreiber", "DFØ (Norwegische Agentur für öffentliches und Finanzmanagement)"], ["Rolle", "Nationaler Service Metadata Publisher (SMP), integriert in das Peppol-Verzeichnis"]]', 'Absender müssen ELMA automatisch abfragen, um die E-Zustelladresse und Fähigkeit eines Käufers vor der Übermittlung zu prüfen — diese Abfrage bestimmt, ob die Ausstellungspflicht ab 2027 für einen bestimmten Empfänger überhaupt gilt.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Norway' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Registre ELMA', '[["Nom complet", "Elektronisk Mottakeradresseregister"], ["Opérateur", "DFØ (Agence norvégienne de gestion publique et financière)"], ["Rôle", "Éditeur national de métadonnées de service (SMP), intégré à l''annuaire Peppol"]]', 'Les émetteurs doivent interroger automatiquement ELMA pour vérifier l''adresse de livraison électronique et la capacité d''un acheteur avant la transmission — cette vérification détermine si l''obligation d''émission de 2027 s''applique à un destinataire donné.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Norway' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'La asimetría 2027–2030', '[["Desde 2027", "Los proveedores deben emitir a compradores registrados en ELMA"], ["Hasta 2030", "Los compradores no están obligados a poder recibir"]]', 'Esto crea una brecha real de tres años en la que la obligación de envío se adelanta a cualquier requisito universal de recepción — diseñada deliberadamente para dar a las pymes un margen más largo para adaptarse.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Norway' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Die Asymmetrie 2027–2030', '[["Ab 2027", "Lieferanten müssen an ELMA-registrierte Käufer ausstellen"], ["Bis 2030", "Käufer sind nicht verpflichtet, empfangsfähig zu sein"]]', 'Dadurch entsteht eine echte dreijährige Lücke, in der die Sendepflicht der allgemeinen Empfangspflicht vorausläuft — bewusst so gestaltet, um KMU einen längeren Anpassungszeitraum zu geben.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Norway' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'L''asymétrie 2027-2030', '[["À partir de 2027", "Les fournisseurs doivent émettre vers des acheteurs enregistrés dans ELMA"], ["Jusqu''en 2030", "Les acheteurs ne sont pas tenus de pouvoir recevoir"]]', 'Cela crée un véritable écart de trois ans où l''obligation d''envoi précède toute exigence universelle de réception — conçu délibérément pour laisser aux PME un délai d''adaptation plus long.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Norway' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Autofacturación', '[["Permitida", "Sí"], ["EHF estructurado requerido", "Desde el 1 de enero de 2027, cuando ambas partes están sujetas a obligaciones contables y el comprador figura en ELMA"]]', 'Si ya practica la autofacturación, no dé por sentado que ese acuerdo queda exento del requisito de formato estructurado una vez que llegue 2027.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Norway' AND dc.section = 'scope_transmission' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Selbstfakturierung', '[["Zulässig", "Ja"], ["Strukturiertes EHF erforderlich", "Ab 1. Januar 2027, sofern beide Parteien buchführungspflichtig sind und der Käufer in ELMA registriert ist"]]', 'Falls Sie bereits selbst fakturieren, gehen Sie nicht davon aus, dass diese Regelung ab 2027 automatisch von der Pflicht zum strukturierten Format ausgenommen ist.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Norway' AND dc.section = 'scope_transmission' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Autofacturation', '[["Autorisée", "Oui"], ["EHF structuré requis", "À partir du 1er janvier 2027, lorsque les deux parties sont soumises à des obligations comptables et que l''acheteur figure dans ELMA"]]', 'Si vous pratiquez déjà l''autofacturation, ne présumez pas que cet arrangement est exempté de l''exigence de format structuré une fois 2027 arrivé.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Norway' AND dc.section = 'scope_transmission' AND dc.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '📊 Post-auditoría hoy, base para más mañana', NULL, NULL, 'Noruega opera actualmente un modelo de post-auditoría sin reporte en tiempo real. Pero la combinación de facturación estructurada obligatoria, contabilidad digital y Peppol crea las condiciones técnicas previas para un futuro cambio hacia el reporte periódico o en tiempo real — sin necesariamente requerir una arquitectura de compensación completa como la de Italia o Polonia.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Norway' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '📊 Heute Post-Audit, Grundlage für morgen', NULL, NULL, 'Norwegen betreibt derzeit ein Post-Audit-Modell ohne Echtzeitmeldung. Doch die Kombination aus verpflichtender strukturierter Rechnungsstellung, digitaler Buchführung und Peppol schafft die technischen Voraussetzungen für einen künftigen Wandel hin zu periodischer oder Echtzeitmeldung — ohne notwendigerweise eine vollständige Clearing-Architektur wie in Italien oder Polen zu erfordern.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Norway' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '📊 Post-audit aujourd''hui, base pour demain', NULL, NULL, 'La Norvège applique actuellement un modèle de post-audit sans déclaration en temps réel. Mais la combinaison de la facturation structurée obligatoire, de la comptabilité numérique et de Peppol crée les conditions techniques préalables à une future évolution vers une déclaration périodique ou en temps réel — sans nécessairement exiger une architecture de contrôle complète comme celle de l''Italie ou de la Pologne.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Norway' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '🇩🇰 Un guiño deliberado a Dinamarca', NULL, NULL, 'La investigación detrás de este mandato consideró explícitamente un requisito de contabilidad digital obligatoria al estilo danés — la reforma noruega está conscientemente inspirada en el enfoque de su vecino, aunque no es idéntica a él.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Norway' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '🇩🇰 Ein bewusster Blick auf Dänemark', NULL, NULL, 'Die Untersuchung hinter dieser Pflicht zog explizit eine dänisch inspirierte verpflichtende digitale Buchführungspflicht in Betracht — Norwegens Reform ist bewusst am Ansatz seines Nachbarn orientiert, wenn auch nicht identisch damit.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Norway' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '🇩🇰 Un clin d''œil délibéré au Danemark', NULL, NULL, 'L''étude à l''origine de cette obligation a explicitement envisagé une exigence de comptabilité numérique obligatoire à la danoise — la réforme norvégienne s''inspire consciemment de l''approche de son voisin, sans en être identique.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Norway' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '📈 La alta adopción existente amortigua el impacto', NULL, NULL, 'Con una adopción voluntaria de EHF/Peppol ya estimada entre el 84 y el 89 %, el mandato de 2027 formaliza en gran medida la práctica actual de las empresas que ya envían y reciben facturas estructuradas — la brecha de cumplimiento es real, pero más estrecha de lo que sugieren las fechas destacadas.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Norway' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '📈 Hohe bestehende Nutzung mildert den Übergang', NULL, NULL, 'Bei einer freiwilligen EHF/Peppol-Nutzung, die bereits auf 84–89 % geschätzt wird, formalisiert die Pflicht ab 2027 größtenteils die aktuelle Praxis von Unternehmen, die bereits strukturierte Rechnungen senden und empfangen — die Compliance-Lücke ist real, aber schmaler als die Schlagzeilen-Daten vermuten lassen.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Norway' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '📈 Une adoption existante élevée atténue le choc', NULL, NULL, 'Avec une adoption volontaire d''EHF/Peppol déjà estimée entre 84 et 89 %, l''obligation de 2027 formalise en grande partie la pratique actuelle des entreprises qui envoient et reçoivent déjà des factures structurées — l''écart de conformité est réel, mais plus étroit que ne le suggèrent les dates phares.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Norway' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '🧾 El SAF-T sigue siendo relevante', NULL, NULL, 'La infraestructura de reporte SAF-T ya existente en Noruega convive con esta reforma — cabe esperar que ambas se refieran cada vez más entre sí a medida que el requisito de contabilidad digital de 2030 tome forma.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Norway' AND dc.section = 'penalties_related' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '🧾 SAF-T bleibt relevant', NULL, NULL, 'Norwegens bestehende SAF-T-Meldeinfrastruktur besteht neben dieser Reform fort — es ist zu erwarten, dass sich beide zunehmend aufeinander beziehen, sobald die digitale Buchführungspflicht ab 2030 Gestalt annimmt.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Norway' AND dc.section = 'penalties_related' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '🧾 Le SAF-T reste pertinent', NULL, NULL, 'L''infrastructure de déclaration SAF-T déjà existante en Norvège coexiste avec cette réforme — les deux devraient de plus en plus se référer l''une à l''autre à mesure que l''exigence de comptabilité numérique de 2030 prend forme.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Norway' AND dc.section = 'penalties_related' AND dc.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Registre su empresa en ELMA', 'Confirme que su organización figura y es localizable en el registro nacional de destinatarios, ahora integrado en el directorio Peppol — es un requisito previo tanto para el envío como para la recepción.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Norway' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Registrieren Sie Ihr Unternehmen bei ELMA', 'Bestätigen Sie, dass Ihre Organisation im nationalen Empfängerregister gelistet und auffindbar ist, das nun in das Peppol-Verzeichnis integriert ist — dies ist eine Voraussetzung sowohl für das Senden als auch für das Empfangen.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Norway' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Inscrivez votre entreprise à ELMA', 'Vérifiez que votre organisation est répertoriée et repérable dans le registre national des destinataires, désormais intégré à l''annuaire Peppol — un prérequis pour l''envoi comme pour la réception.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Norway' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Elija un proveedor de Punto de Acceso Peppol certificado', 'Elija un proveedor bien antes del tercer trimestre de 2026 para disponer de tiempo de integración y pruebas antes del plazo de enero de 2027.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Norway' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Wählen Sie einen zertifizierten Peppol-Access-Point-Anbieter', 'Wählen Sie einen Anbieter deutlich vor dem dritten Quartal 2026, um Zeit für Integration und Tests vor der Frist im Januar 2027 zu haben.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Norway' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Choisissez un fournisseur d''Access Point Peppol certifié', 'Choisissez un fournisseur bien avant le T3 2026 afin de disposer du temps nécessaire à l''intégration et aux tests avant l''échéance de janvier 2027.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Norway' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Confirme que su ERP puede emitir en EHF 3.0', 'Valide que las facturas salientes están correctamente estructuradas como XML Peppol BIS Billing 3.0 — es el mismo formato subyacente independientemente de si lo llama "EHF" o "Peppol BIS" internamente.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Norway' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bestätigen Sie, dass Ihr ERP EHF 3.0 ausgeben kann', 'Prüfen Sie, dass ausgehende Rechnungen korrekt als strukturiertes Peppol-BIS-Billing-3.0-XML formatiert sind — es handelt sich intern um dasselbe zugrunde liegende Format, egal ob Sie es "EHF" oder "Peppol BIS" nennen.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Norway' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Confirmez que votre ERP peut émettre en EHF 3.0', 'Vérifiez que les factures sortantes sont correctement structurées en XML Peppol BIS Billing 3.0 — il s''agit du même format sous-jacent, que vous l''appeliez en interne « EHF » ou « Peppol BIS ».' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Norway' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Incorpore la consulta a ELMA en su flujo de facturación', 'Consulte ELMA automáticamente antes de la transmisión para comprobar si un destinatario dado está registrado y qué capacidad ha declarado — esto determina si la obligación de formato estructurado se aplica a esa factura concreta.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Norway' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Integrieren Sie die ELMA-Abfrage in Ihren Rechnungsworkflow', 'Fragen Sie ELMA automatisch vor der Übermittlung ab, um zu prüfen, ob ein bestimmter Empfänger registriert ist und welche Fähigkeit er angegeben hat — dies bestimmt, ob die Pflicht zum strukturierten Format für diese konkrete Rechnung gilt.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Norway' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Intégrez la vérification ELMA à votre flux de facturation', 'Interrogez automatiquement ELMA avant la transmission pour vérifier si un destinataire donné est enregistré et quelle capacité il a déclarée — cela détermine si l''obligation de format structuré s''applique à cette facture précise.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Norway' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Entidades extranjeras: confirme su estado de obligación contable noruega', 'Si tiene una presencia local que activa las normas contables noruegas, planifique el cumplimiento idéntico de EHF — no existe un régimen más ligero separado para empresas no noruegas.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Norway' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Ausländische Unternehmen: Klären Sie Ihren norwegischen Buchführungspflichtstatus', 'Wenn Sie eine lokale Präsenz haben, die norwegische Buchführungsregeln auslöst, planen Sie eine identische EHF-Konformität ein — es gibt kein separates, abgeschwächtes Regime für nicht-norwegische Unternehmen.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Norway' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Entités étrangères : vérifiez votre statut d''obligation comptable norvégienne', 'Si vous avez une présence locale déclenchant les règles comptables norvégiennes, prévoyez une conformité EHF identique — il n''existe pas de régime allégé distinct pour les entreprises non norvégiennes.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Norway' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Empiece ya a planificar su actualización de contabilidad digital de 2030', 'Aunque la recepción no sea obligatoria hasta 2030, el margen de tres años está ahí para aprovecharlo — no deje el requisito de recepción y procesamiento automático para el último momento.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Norway' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Beginnen Sie jetzt mit der Planung Ihres digitalen Buchführungs-Upgrades für 2030', 'Auch wenn der Empfang erst 2030 verpflichtend wird, sollte der dreijährige Vorlauf genutzt werden — schieben Sie die Anforderung zum automatischen Empfang und zur Verarbeitung nicht bis zur letzten Minute auf.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Norway' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Commencez dès maintenant à planifier votre mise à niveau comptable numérique de 2030', 'Même si la réception ne devient obligatoire qu''en 2030, le délai de trois ans est là pour être utilisé — ne repoussez pas l''exigence de réception et de traitement automatiques jusqu''à la dernière minute.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Norway' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Aproveche el apoyo gratuito disponible', 'Skatteetaten y Digdir ofrecen orientación, documentación SAF-T e información sobre Peppol, incluidos seminarios web gratuitos — realmente vale la pena aprovecharlo dado que los detalles técnicos aún se están finalizando hasta finales de 2026.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Norway' AND ds.sort_order = 6;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Nutzen Sie die kostenlose verfügbare Unterstützung', 'Skatteetaten und Digdir bieten Beratung, SAF-T-Dokumentation und Peppol-Informationen an, einschließlich kostenloser Webinare — angesichts der technischen Details, die noch bis Ende 2026 finalisiert werden, lohnt sich das wirklich.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Norway' AND ds.sort_order = 6;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Profitez du soutien gratuit disponible', 'Skatteetaten et Digdir proposent des conseils, une documentation SAF-T et des informations sur Peppol, y compris des webinaires gratuits — cela vaut vraiment la peine d''en profiter compte tenu des détails techniques encore en cours de finalisation jusqu''à fin 2026.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Norway' AND ds.sort_order = 6;

